import pathlib,re
for prefix in ['SLINGER','ICORE','EcoScience','NOVO','MANAKOA','MERCATA']:
 f=next(f for f in pathlib.Path('.').glob('*.txt') if f.name.startswith(prefix));s=f.read_text();print('\\n',f.name)
 if prefix in ['SLINGER','ICORE']:
  for p,c in enumerate(re.split(r'--- page \\d+ ---',s)[1:],1):
   if (prefix=='SLINGER' and p in [3,4]) or(prefix=='ICORE' and p in [5,6]):print('PAGE',p,c)
 else: print(s[:16000])
